  function coneHit(x,y,ang){const c=A.P.cone,T=tile(),dx=x-A.b1.x,dy=y-A.b1.y,d=Math.hypot(dx,dy);if(d>c.len*T)return false;const da=Math.atan2(Math.sin(Math.atan2(dy,dx)-ang),Math.cos(Math.atan2(dy,dx)-ang));return Math.abs(da)<(c.half||22)*D;}
  function heatPhase(){const h=A.P.heat,c=Math.max(0,A.since-GRACE)%h.every,k=Math.floor(Math.max(0,A.since-GRACE)/h.every);return {c,par:k%2,warn:c<h.warn,burn:c>=h.warn&&c<h.warn+0.35};}
