        if(FL){c.save();c.beginPath();c.rect(0,y-4,W,8);c.clip();flDraw(c,'b','#8cc8ff',0.4,0,y-4,W,y+4);flDraw(c,'s','#e0f2ff',0.85,0,y-4,W,y+4);c.restore();}
        const sx=((t*0.45+i*0.23)%1.3-0.15)*W;
