      if(z.st==='done'&&k===z.pick)col=z.ok?'rgba(120,255,140,.95)':'rgba(255,60,70,.95)';if(z.st==='done'&&!z.ok&&k===z.pz.ans)col='rgba(120,255,140,.7)';
