      if(B.stop){if(!b.stopped&&b.age>=B.stop.at){b.stopped=1;b.v=0;}
        if(b.stopped===1&&b.age>=B.stop.at+B.stop.wait){b.stopped=2;if(B.stop.reaim)b.a=Math.atan2(py-b.by,px-b.bx);b.v=(B.stop.go||0)*T;}}
      if(B.accel&&!b.stopped){b.v*=Math.pow(B.accel,dt);if(B.max)b.v=Math.min(b.v,B.max*T);}
