      if(h.k==='nova'){h.r+=h.v*dt;for(const r of A.hz)if(r.k==='rock'&&!h.hit.has(r)&&Math.hypot(r.x-h.x,r.y-h.y)<h.r){h.hit.add(r);r.hits=(r.hits||0)+1;if(r.hits>=2){r.dead=1;A.hz.push({k:'anim',fx:'impact_earth',x:r.x,y:r.y,size:T*2.6,age:0});}}if(h.r>h.max){if(h.back&&!h.ret){h.ret=1;h.v=-Math.abs(h.v);h.ga+=Math.PI;h.hitP=0;h.hit=new Set();}else if(!h.back)continue;}if(h.ret&&h.r<T*0.6)continue;}
