      c.fillStyle='rgba(0,0,0,.45)';c.beginPath();c.ellipse(x+1,y+T*0.55,T*0.55,T*0.18,0,0,TAU);c.fill();
      c.fillStyle='#1c120c';c.fillRect(x-T*0.42,y+T*0.1,2,T*0.45);c.fillRect(x+T*0.42-2,y+T*0.1,2,T*0.45);c.fillRect(x-1,y+T*0.15,2,T*0.42);
      c.fillStyle='#2a1c14';c.beginPath();c.ellipse(x,y,T*0.55,T*0.26,0,0,Math.PI);c.fill();c.fillStyle='#4a3424';c.fillRect(Math.round(x-T*0.55),Math.round(y-1),Math.round(T*1.1),2);
