    view.append(el('div',{class:'bvgrid'},[el('div',{class:'arenawrap'},[cv,hud,phud,ctl,el('div',{class:'ctlhint',text:'You play: move with WASD or arrow keys, or press and hold on the arena to walk toward your finger. In phases where you shoot (Vitrea, Aion), you fire automatically at the nearest target, or toward the mouse pointer.'})]),pl]));
