    setupRoom(B);sizeArena();A.b1=body();A.b2=body();A.b2.x=A.W*0.62;A.bub=[];A.dying=null;A.pl=newPlayer();A.player=A.pl;A.stat=newStat();A.fl=[];setPhase(0,false);
