    A.F1=frames(B.frames,B.atk,B.pal,74);A.F2=B.twin?frames(B.frames2,B.atk2,B.pal2,74):null;A.shots={};A.allies=null;A.AF={};A.stars=null;(B.allies||[]).forEach(al=>{A.AF[al.id]=frames(al.frames,al.atk,al.pal,52);});
